\]
\[
\text{Leerguthaben} = 3,00 \text{ US-Dollar}
\]

\[
\text{Endpris der Levensmiddel} = 40,00 + 5,00 + 10,00 + 3,00 = 58,00 \text{ US-Dollar}
\]

